def investigate(context, acquire):
    hist = acquire("history")
    # Family: put in {OR IGNORE, OR REPLACE, ON CONFLICT DO UPDATE}
    # channel in {changes(), total_changes(main), total_changes(main)+total_changes(other)}
    # instrumentation: none or one AFTER INSERT trigger logging one row
    # We simulate all 18 combos and keep those consistent with receipts.

    def simulate(put_mode, chan_mode, trig, actions):
        # state: dict key->value committed; open txn per connection
        committed = {}
        txn = {"main": None, "other": None}
        # counters
        ch_main = 0
        tc_main = 0
        tc_other = 0
        # channel value emitted at end (last write's counter reading)
        last_chan = 0
        for a in actions:
            op = a.get("op")
            conn = a.get("connection", "main")
            if op == "begin":
                txn[conn] = {}
            elif op == "commit":
                t = txn[conn]
                if t is not None:
                    for k, v in t.items():
                        committed[k] = v
                txn[conn] = None
            elif op == "rollback":
                txn[conn] = None
            elif op == "put":
                k = a.get("key")
                v = a.get("value")
                t = txn[conn]
                target = committed if t is None else t
                # determine effect
                if k in target:
                    if put_mode == "ignore":
                        changed = 0
                    elif put_mode == "replace":
                        target[k] = v
                        changed = 1
                    else:  # update
                        target[k] = v
                        changed = 1
                else:
                    target[k] = v
                    changed = 1
                # trigger fires on actual insert (new row), not on update/ignore
                trig_fire = 0
                if changed and k not in target:
                    pass
                # need to know if it was an insert: key was absent before
                # recompute: absent before means changed and it was new
                # We'll track: inserted = (k not in target_before)
                # redo properly below
                # counters
                if chan_mode == "changes":
                    ch_main = changed
                    last_chan = ch_main
                elif chan_mode == "tc_main":
                    tc_main += changed
                    last_chan = tc_main
                else:
                    if conn == "main":
                        tc_main += changed
                    else:
                        tc_other += changed
                    last_chan = tc_main + tc_other
            elif op == "update":
                k = a.get("key")
                v = a.get("value")
                t = txn[conn]
                target = committed if t is None else t
                if k in target:
                    target[k] = v
                    changed = 1
                else:
                    changed = 0
                if chan_mode == "changes":
                    ch_main = changed
                    last_chan = ch_main
                elif chan_mode == "tc_main":
                    tc_main += changed
                    last_chan = tc_main
                else:
                    if conn == "main":
                        tc_main += changed
                    else:
                        tc_other += changed
                    last_chan = tc_main + tc_other
            elif op == "delete":
                k = a.get("key")
                t = txn[conn]
                target = committed if t is None else t
                if k in target:
                    del target[k]
                    changed = 1
                else:
                    changed = 0
                if chan_mode == "changes":
                    ch_main = changed
                    last_chan = ch_main
                elif chan_mode == "tc_main":
                    tc_main += changed
                    last_chan = tc_main
                else:
                    if conn == "main":
                        tc_main += changed
                    else:
                        tc_other += changed
                    last_chan = tc_main + tc_other
        return last_chan, len(committed), sum(committed.values())

